mapper.select:
select b.book_id as bookId, b.isbn as isbn, b.title as title, coalesce(sum(oi.qty), 0) as saleQty, coalesce(sum(oi.share_amount), 0) as saleAmount, coalesce(sum(oi.share_amount - oi.cost_price * oi.qty), 0) as grossProfit, coalesce(c.category_name, '未分类') as categoryName from biz_order o join biz_order_item oi on oi.order_id = o.order_id left join biz_book b on b.book_id = oi.book_id left join biz_category c on c.category_id = b.category_id where o.store_id = 1 and o.status in (2, 3, 4) and oi.book_id > 0 and o.create_time >= #{start} and o.create_time < date_add(#{end}, interval 1 day) group by b.book_id, b.isbn, b.title, c.category_name
order by grossProfit desc, saleQty desc order by saleQty desc, saleAmount desc
limit #{limit}
